import sys, os, re, time, json, datetime; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from kl import *
tee('k85')
cn, _ = up('main'); wait_nodes_ready()
NS = ns('k85')
server = ko('config', 'view', '--minify', '-o', 'jsonpath={.clusters[0].cluster.server}')
def kt(tok, *a): return sh('kubectl', f'--server={server}', f'--token={tok}', '--insecure-skip-tls-verify', *a, timeout=60)
def short(o, n=1, w=300): return [re.sub(r'\s+', ' ', l)[:w] for l in o.strip().splitlines() if l.strip()][:n]
print(f'集群 {cn};用户模拟(impersonation)让一个已通过认证的身份以另一个用户 / 组的名义发请求,服务端的鉴权、准入、审计都按被模拟者处理。kubectl 用 --as / --as-group / --as-uid')

print('== 一:管理员模拟别人')
rc, o = k('get', 'pods', '-n', NS, '--as=alice'); print(f'  kubectl get pods --as=alice(alice 没有任何权限):退出码 {rc};{short(o)}')
k('create', 'rolebinding', 'alice-view', '-n', NS, '--clusterrole=view', '--user=alice'); time.sleep(1)
rc, o = k('get', 'pods', '-n', NS, '--as=alice'); print(f'  给 alice 绑定 view 之后:退出码 {rc};{short(o)}')
rc, o = k('get', 'pods', '-n', 'default', '--as=alice'); print(f'  alice 访问别的命名空间 default:退出码 {rc};{short(o)}')
rc, o = k('auth', 'whoami', '--as=alice', '--as-group=dev', '--as-group=ops', '-o', 'json'); ui = json.loads(o)['status']['userInfo']; print(f'  kubectl auth whoami --as=alice --as-group=dev --as-group=ops:username={ui["username"]};groups={ui["groups"]}(服务端自动补了 system:authenticated)')
rc, o = k('auth', 'whoami', '--as=alice', '--as-uid=uid-123', '--as-user-extra=scopes=read', '-o', 'json'); ui = json.loads(o)['status']['userInfo']; print(f'  加 --as-uid=uid-123 --as-user-extra=scopes=read:uid={ui.get("uid")};extra={ui.get("extra")}')
rc, o = k('get', 'pods', '-n', NS, '--as-group=dev'); print(f'  只写 --as-group 不写 --as:退出码 {rc};{short(o)}')

print('== 二:谁有资格模拟——需要对 users / groups / serviceaccounts 的 impersonate 权限')
k('create', 'sa', 'caller', '-n', NS); tok = ko('create', 'token', 'caller', '-n', NS)
k('create', 'rolebinding', 'caller-view', '-n', NS, '--clusterrole=view', f'--serviceaccount={NS}:caller'); time.sleep(1)
rc, o = kt(tok, 'get', 'pods', '-n', NS); print(f'  ServiceAccount caller(只有 view)直接 get pods:退出码 {rc};{short(o) or "(成功,有结果)"}')
rc, o = kt(tok, 'get', 'pods', '-n', NS, '--as=alice'); print(f'  caller 加 --as=alice:退出码 {rc};{short(o)}')
k('create', 'clusterrole', 'impersonate-alice', '--verb=impersonate', '--resource=users', '--resource-name=alice'); k('create', 'clusterrolebinding', 'caller-imp', '--clusterrole=impersonate-alice', f'--serviceaccount={NS}:caller'); time.sleep(1)
rc, o = kt(tok, 'get', 'pods', '-n', NS, '--as=alice'); print(f'  授予 impersonate users(resourceNames: [alice])之后 --as=alice:退出码 {rc};{short(o) or "(成功)"}')
rc, o = kt(tok, 'get', 'pods', '-n', NS, '--as=bob'); print(f'  换成 --as=bob:退出码 {rc};{short(o)}')
rc, o = kt(tok, 'get', 'pods', '-n', NS, '--as=alice', '--as-group=system:masters'); print(f'  --as=alice --as-group=system:masters(想借 masters 组提权):退出码 {rc};{short(o)}')
rc, o = kt(tok, 'auth', 'whoami', '--as=alice', '-o', 'json'); print(f'  模拟成功时 whoami 看到的是:{json.loads(o)["status"]["userInfo"]["username"]}(caller 自己的身份被替换,不是叠加)')

print('== 三:权限是取被模拟者的,不是两者之和')
rc, o = kt(tok, 'get', 'secrets', '-n', NS, '--as=alice'); print(f'  caller 模拟 alice 读 secrets(alice 只有 view,view 不含 secrets):退出码 {rc};{short(o)}')
k('create', 'rolebinding', 'caller-edit', '-n', NS, '--clusterrole=edit', f'--serviceaccount={NS}:caller'); time.sleep(1)
rc, o = kt(tok, 'get', 'secrets', '-n', NS); print(f'  给 caller 自己 edit 之后,caller 自己读 secrets:退出码 {rc};{short(o) or "(成功)"}')
rc, o = kt(tok, 'get', 'secrets', '-n', NS, '--as=alice'); print(f'  但 caller 模拟 alice 读 secrets 仍然:退出码 {rc};{short(o)}(模拟之后用的是 alice 的权限)')
rc, o = k('auth', 'can-i', '--list', '-n', NS, '--as=alice'); print(f'  管理员看 alice 能做什么(auth can-i --list --as=alice):{len(o.strip().splitlines()) - 1} 行;前几条:{[re.sub(chr(32) + "+", " ", l)[:70] for l in o.strip().splitlines()[1:4]]}')
k('delete', 'clusterrolebinding', 'caller-imp'); k('delete', 'clusterrole', 'impersonate-alice'); k('delete', 'ns', NS, '--wait=false')
